data.server-side-coordination#Server-Side Coo:
For server-side applications, you can create automated coordination services:
import { LoxleySDK, LoxleyEventType } from '@loxley/sdk'
import { hardhat } from 'viem/chains'
class E3CoordinationServer {
  private sdk: LoxleySDK
  constructor(privateKey: string, rpcUrl: string) {
    // Use the static factory for convenience
    this.sdk = LoxleySDK.create({
      rpcUrl,
      privateKey: privateKey as `0x${string}`,
